func (q *Queries) UpdateProviderPaymentStatus(ctx context.Context, arg UpdateProviderPaymentStatusParams) (ProviderPayment, error) {
	row := q.db.QueryRow(ctx, updateProviderPaymentStatus,
		arg.Status,
		arg.Raw,
		arg.ID,
		arg.FromStatus,
	)
	var i ProviderPayment
	err := row.Scan(
		&i.ID,
		&i.TransactionID,
		&i.Provider,
		&i.Direction,
		&i.ProviderRef,
		&i.Status,
		&i.AmountMinor,
		&i.Currency,
		&i.Raw,
		&i.DestinationID,
		&i.ReserveJournalID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
